package com.sekai.world.actor.model;

public class Actor {
    private Long id; private Long worldId; private Long factionId; private Long locationId; private String name; private String role; private String profileJson; private String stateJson; private Integer energy; private Integer mood; private String status;
    public Actor() {}
    public Actor(Long id,Long worldId,Long factionId,Long locationId,String name,String role,String profileJson,String stateJson,Integer energy,Integer mood,String status){this.id=id;this.worldId=worldId;this.factionId=factionId;this.locationId=locationId;this.name=name;this.role=role;this.profileJson=profileJson;this.stateJson=stateJson;this.energy=energy;this.mood=mood;this.status=status;}
    public Long getId(){return id;} public void setId(Long v){id=v;} public Long getWorldId(){return worldId;} public void setWorldId(Long v){worldId=v;} public Long getFactionId(){return factionId;} public void setFactionId(Long v){factionId=v;} public Long getLocationId(){return locationId;} public void setLocationId(Long v){locationId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getProfileJson(){return profileJson;} public void setProfileJson(String v){profileJson=v;} public String getStateJson(){return stateJson;} public void setStateJson(String v){stateJson=v;} public Integer getEnergy(){return energy;} public void setEnergy(Integer v){energy=v;} public Integer getMood(){return mood;} public void setMood(Integer v){mood=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;}
    public Long id(){return id;} public Long worldId(){return worldId;} public Long factionId(){return factionId;} public Long locationId(){return locationId;} public String name(){return name;} public String role(){return role;} public String profileJson(){return profileJson;} public String stateJson(){return stateJson;} public Integer energy(){return energy;} public Integer mood(){return mood;} public String status(){return status;}
}
